# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SON OSMANLI MEBUSAN MECLİSİ VE MİSAKIMİLLÎ (28 OCAK 1920)</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Mustafa Kemal\'in Mebuslardan İstekleri</text>\n  <text x="180" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• Seçimler yapıldı: Mustafa Kemal Erzurum mebusu</text>\n  <text x="180" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• İstek 1: Kendisinin Meclis Başkanı seçilmesi</text>\n  <text x="180" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• İstek 2: Müdafaa-i Hukuk Grubu\'nun kurulması</text>\n  <text x="180" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">  (Yerine Felah-ı Vatan Grubu kuruldu)</text>\n  <text x="180" y="200" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• İstek 3: Misakımillî kararlarının kabul edilmesi</text>\n  <text x="180" y="224" text-anchor="middle" font-size="11" fill="#334155">12 Ocak 1920\'de İstanbul\'da Meclis toplandı</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Misakımillî (Millî Yemin) Kararları (KAPSAR)</text>\n  <text x="520" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• K - Kapitülasyonlar: Siyasi, mali, adli kısıtlamalar red!</text>\n  <text x="520" y="120" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• A - Azınlıklar: Komşu ülkelerdeki Müslüman hakları kadar</text>\n  <text x="520" y="144" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• P - Plebisit (Halk Oylaması): Kars, Ardahan, Batum,</text>\n  <text x="520" y="164" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">      Batı Trakya ve Arap topraklarında halk oylaması</text>\n  <text x="520" y="188" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• S - Sınırlar: Mondros öncesi Türk-İslam çoğunluğu bölünmez</text>\n  <text x="520" y="212" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• B - Boğazlar: Güvenlik sağlanırsa dünya ticaretine açık</text>\n  <text x="520" y="232" text-anchor="middle" font-size="11" fill="#166534">Tam Bağımsızlık ve Vatanın Bütünlüğü belgesidir!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İSTANBUL\'UN RESMEN İŞGALİ (16 MART 1920) VE SONUÇLARI</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">İşgalin Nedeni ve Gelişimi</text>\n  <text x="180" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">• Neden: Mebusan Meclisinin Misakımillî\'yi</text>\n  <text x="180" y="116" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">  kabul edip tüm dünyaya ilan etmesi</text>\n  <text x="180" y="142" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">• 16 Mart 1920: İtilaf Devletleri İstanbul\'u</text>\n  <text x="180" y="162" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">  resmen işgal etti (Şehzadebaşı Karakolu baskını)</text>\n  <text x="180" y="188" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">• Mebusan Meclisi basıldı, milletvekilleri</text>\n  <text x="180" y="208" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">  tutuklanarak Malta Adası\'na sürgün edildi</text>\n  <text x="180" y="228" text-anchor="middle" font-size="11" fill="#713f12">Mustafa Kemal\'in ileri görüşlülüğü kanıtlandı!</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Mustafa Kemal\'in Aldığı Tedbirler</text>\n  <text x="520" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">• Telgrafçı Manastırlı Hamdi Bey işgali bildirdi</text>\n  <text x="520" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">• İstanbul ile haberleşme kesildi</text>\n  <text x="520" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">• Geyve ve Ulukışla demir yolu tahrip edildi</text>\n  <text x="520" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">• Anadolu\'daki İtilaf subayları tutuklandı</text>\n  <text x="520" y="200" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">• Ankara\'da olağanüstü yetkilere sahip</text>\n  <text x="520" y="220" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">  Büyük Millet Meclisinin açılması hızlandı!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">BÜYÜK MİLLET MECLİSİNİN AÇILIŞI (23 NİSAN 1920) VE ÖZELLİKLERİ</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">24 Nisan 1920 Önergesi Kararları</text>\n  <text x="180" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">• Hükûmet kurmak zorunludur (Kurucu Meclis)</text>\n  <text x="180" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">• Geçici bir hükûmet başkanı tanımak veya</text>\n  <text x="180" y="142" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">  padişah vekili atamak doğru değildir (Bağımsız)</text>\n  <text x="180" y="168" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">• BMM\'nin üstünde hiçbir güç yoktur! (Ulusal Egemenlik)</text>\n  <text x="180" y="194" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">• Yasama ve yürütme yetkisi BMM\'ye aittir</text>\n  <text x="180" y="220" text-anchor="middle" font-size="11" fill="#881337">Güçler Birliği + Meclis Hükûmeti Sistemi</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Birinci BMM\'nin Temel Nitelikleri</text>\n  <text x="520" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">• Demokratik ve Millîdir: Üyeleri seçimle geldi,</text>\n  <text x="520" y="116" text-anchor="middle" font-size="11" fill="#164e63">  içinde azınlık milletvekili yer almadı</text>\n  <text x="520" y="142" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">• Olağanüstü Yetkilidir: Hızlı karar almak için</text>\n  <text x="520" y="162" text-anchor="middle" font-size="11" fill="#164e63">  yasama, yürütme ve yargıyı kendinde topladı</text>\n  <text x="520" y="188" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">• Meclis Başkanı = Hükûmet (İcra Vekilleri) Başkanı</text>\n  <text x="520" y="218" text-anchor="middle" font-size="11" fill="#0f172a">Öncelikli hedef: Vatanı işgalden kurtarmak!</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
